export interface AiUsageContext {
    schemaVersion: typeof AI_USAGE_SCHEMA_VERSION;
    pricingVersion: typeof AI_USAGE_PRICING_VERSION;
    entryId: string;
    requestId: string;
    parentRequestId?: string;
    entryKind: AiUsageEntryKind;
    category: AiUsageCategory;
    operation: string;
    source: string;
    provider: string;
    model?: string;
    channelID?: string;
    quantity?: number;
    unit?: AiUsageUnit;
    resourceType?: AiUsageResourceType;
    resourceId?: string;
}

export interface AiUsageContextInput {
    entryId?: string;
    requestId?: string;
    parentRequestId?: string;
    entryKind?: AiUsageEntryKind;
    category?: AiUsageCategory;
    operation?: string;
    source?: string;
    provider?: string;
    model?: string;
    channelID?: string;
    quantity?: number;
    unit?: AiUsageUnit;
    resourceType?: AiUsageResourceType;
    resourceId?: string;
}

export interface AiUsageTransaction {
  id: string;
  requestId: string | null;
  occurredAt: string;
  entryKind: AiUsageEntryKind;
  category: AiUsageReceiptCategory;
  operation: string;
  source?: string | null;
  adjustmentType?: string | null;
  provider: string;
  model: string | null;
  quantity: number | null;
  unit: AiUsageUnit | null;
  credits: number;
  resourceType: AiUsageResourceType | null;
  resourceId: string | null;
  itemized: boolean;
}

